    cmd_path: Path, cmd_params: list[str], color: bool | None = None
) -> t.Iterator[tuple[t.TextIO, bool | None]]:








    import subprocess


    env = dict(os.environ)






    cmd_name = cmd_path.stem
    if WIN:




