            file = _default_text_stderr()
        else:
            file = _default_text_stdout()



        if file is None:
            return

    match message:
        case str() | bytes() | bytearray():
            out = message
        case None:
            out = ""
        case _:
            out = str(message)

    if nl:
        if isinstance(out, str):
            out += "\n"
        else:
            out += b"\n"

    if not out:
        file.flush()
        return





    if isinstance(out, (bytes, bytearray)):
