            pydantic_js_extra=pydantic_js_extra,
        )
        exclude_if = d.info.exclude_if

        return core_schema.computed_field(
            d.cls_var_name,
            return_schema=return_type_schema,
            alias=d.info.alias,
            serialization_exclude_if=exclude_if,
