        ge = constraint.ge
        if s and s['type'] in _ORDERING_SCHEMA_TYPES:
            s = s.copy()
            s['ge'] = ge  # pyright: ignore[reportGeneralTypeIssues]
        else:

            def check_ge(v: Any) -> bool:
                return v >= ge

            s = _check_func(check_ge, f'>= {ge}', s)
