        lt = constraint.lt
        if s and s['type'] in _ORDERING_SCHEMA_TYPES:
            s = s.copy()
            s['lt'] = lt  # pyright: ignore[reportGeneralTypeIssues]
        else:

            def check_lt(v: Any) -> bool:
                return v < lt

            s = _check_func(check_lt, f'< {lt}', s)
